class Account {
    // 클래스 밖에서는 못 쓰는 잔액이에요.
    private int balance;

    // 처음 잔액을 받아 필드에 담아요.
    Account(int balance) {
        this.balance = balance;
    }

    // 잔액을 읽어서 돌려줘요.
    int getBalance() {
        return balance;
    }

    // 돌려주는 값이 없어서 void예요.
    void withdraw(int money) {
        // 잔액보다 많이는 못 빼요.
        if (money <= balance) {
            balance -= money;
        }
    }
}

class Main {
    public static void main(String[] args) {
        // 처음 잔액과 뺄 금액이에요.
        int start = 10000;
        int money = 3000;
        Account acc = new Account(start);
        // 잔액에서 money만큼 빼려는 줄이에요.
        acc.balance -= money;
        // 잔액은 메서드로 읽어요.
        System.out.println("잔액: " + acc.getBalance());
    }
}
